script:
(function () {
  'use strict';
  // IRA spend it or save it: cash out a traditional IRA now or keep it invested.
  //   Cash out: federal withholding = amount x chosen rate (10% default). Federal tax =
  //     tax(other taxable income + amount) - tax(other taxable income) with 2026 brackets and the
  //     standard deduction (or amount x your rate). 10% additional tax before 59 1/2 on the part not
  //     covered by an exception (capped exceptions: first home $10,000 lifetime, birth or adoption
  //     $5,000, emergency personal expense $1,000; medical, unemployed health insurance and education
  //     up to the qualifying cost; disability, terminal illness, IRS levy and reservist: all of it).
  //     State tax at a flat rate. Federal settle-up at filing = federal tax + 10% tax - withheld.
  //   Keep invested: value at retirement = amount x (1 + return)^(years); after tax = value x
  //     (1 - retirement tax rate).
  // CHECKS (Node, scratch tests, each against a hand calculation):
  //   Defaults ($20,000, age 40, single, $60,000 other income, 10% withheld, 5% state): taxable
  //   income $43,900 -> $63,900, bracket tax $5,020 -> $8,770, federal tax $3,750.00; 10% tax $2,000;
  //   state $1,000; kept $13,250.00; withheld $2,000, still owed at filing $3,750.00.
  //   Kept invested: 20,000 x 1.06^25 = $85,837.41; after 20% tax $68,669.93.
  //   Exceptions: first home with $15,000 of costs -> $10,000 cap, 10% tax $1,000; birth $8,000 ->
  //   $5,000 cap, $1,500; emergency -> $1,000 cap, $1,900; medical $3,000 -> $1,700; disability -> $0;
  //   age 60 -> none. 40% withheld -> $2,250 refund; own 12% rate -> $2,400 federal.
  // ---- 2026 FEDERAL CONSTANTS AND RULES (tax year 2026) ------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21), sections
  //   4.01 and 4.03 - same constants as income-tax-calculator.
  // IRA withholding: 10% on nonperiodic payments unless you elect another rate on Form W-4R
  //   (IRS Pub. 590-B (2025), "Withholding"; IRC 3405(b)).
  // 10% additional tax before 59 1/2 and its exceptions, with the $10,000 first-home, $5,000
  //   birth/adoption and $1,000 emergency limits: IRC 72(t); IRS Pub. 590-B (2025), "Early
  //   Distributions". The age 55 separation-from-service exception does not apply to IRAs
  //   (IRC 72(t)(3)(A)).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var ADDITIONAL_TAX = 0.10, EARLY_AGE = 59.5;
  // Exceptions: cap = most of the withdrawal it can cover (Infinity = no cap), amount = needs a
  // qualifying-cost input, all = covers the whole withdrawal.
  var EXCEPTIONS = {
    none:       { cover: 'none' },
    medical:    { cover: 'amount', cap: Infinity, hint: 'Medical costs you paid this year above 7.5% of your AGI.' },
    insurance:  { cover: 'amount', cap: Infinity, hint: 'Health insurance premiums paid this year after 12 weeks of unemployment pay.' },
    education:  { cover: 'amount', cap: Infinity, hint: 'Qualified tuition, fees, books and supplies paid this year.' },
    home:       { cover: 'amount', cap: 10000, hint: 'First-home costs. The lifetime limit is $10,000.' },
    birth:      { cover: 'amount', cap: 5000, hint: 'Up to $5,000 per child, within a year of the birth or adoption.' },
    emergency:  { cover: 'amount', cap: 1000, hint: 'One distribution a year of up to $1,000.' },
    disability: { cover: 'all' },
    terminal:   { cover: 'all' },
    levy:       { cover: 'all' },
    reservist:  { cover: 'all' }
  };
  // ------------------------------------------------------------------------------------------------

  function ordinaryTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }
  function federalTaxOn(amount, t) {
    if (amount <= 0) return 0;
    if (t.mode === 'rate') return amount * t.rate;
    var sd = STANDARD_DEDUCTION[t.status];
    return ordinaryTax(Math.max(0, t.income + amount - sd), t.status) - ordinaryTax(Math.max(0, t.income - sd), t.status);
  }
  function exemptPart(amount, age, exception, excAmount) {
    if (age >= EARLY_AGE) return amount;
    var e = EXCEPTIONS[exception] || EXCEPTIONS.none;
    if (e.cover === 'all') return amount;
    if (e.cover === 'amount') return Math.min(amount, Math.max(0, excAmount), e.cap);
    return 0;
  }

  // p: { amount, age, retire, rate, withhold, exception, excAmount, state, retireTax, tax: {...} }
  function compute(p) {
    var a = p.amount, withheld = a * p.withhold, fed = federalTaxOn(a, p.tax);
    var exempt = exemptPart(a, p.age, p.exception, p.excAmount);
    var addl = (a - exempt) * ADDITIONAL_TAX, state = a * p.state;
    var totalTax = fed + addl + state;
    var years = Math.max(0, p.retire - p.age), value = a * Math.pow(1 + p.rate, years);
    var rows = [];
    for (var k = 0; k <= Math.floor(years + 1e-9); k++) rows.push({ age: p.age + k, balance: a * Math.pow(1 + p.rate, k) });
    if (years - Math.floor(years + 1e-9) > 1e-9) rows.push({ age: p.retire, balance: value });
    return { withheld: withheld, received: a - withheld, fed: fed, exempt: exempt, addl: addl, state: state,
             totalTax: totalTax, net: a - totalTax, settle: fed + addl - withheld, years: years,
             value: value, valueAfter: value * (1 - p.retireTax), rows: rows };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function el(id) { return document.getElementById(id); }
  function num(id) {
    var raw = el(id).value;
    if (raw === '' || raw === null || raw === undefined) return NaN;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { el(id).textContent = text; }
  function fillRows(id, rows) {
    var body = el(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }
  function ageText(a) { return Math.abs(a - Math.round(a)) < 1e-9 ? String(Math.round(a)) : a.toFixed(1); }
  var OUTPUTS = ['isNet', 'isKeep', 'isTaxes', 'isKeepAfter', 'isGross', 'isWithheld', 'isReceived', 'isFed', 'isAddl', 'isStateTax', 'isSettle'];

  function update() {
    var mode = el('isTaxMode').value, exception = el('isException').value;
    var ex = EXCEPTIONS[exception] || EXCEPTIONS.none;
    var age = num('isAge');
    el('isBracketFields').classList.toggle('form-field-hidden', mode !== 'brackets');
    el('isRateField').classList.toggle('form-field-hidden', mode !== 'rate');
    el('isExceptionField').classList.toggle('form-field-hidden', !(isNaN(age) || age < EARLY_AGE));
    el('isExcAmountField').classList.toggle('form-field-hidden', !(ex.cover === 'amount' && (isNaN(age) || age < EARLY_AGE)));
    if (ex.hint) set('isExcHint', ex.hint);
    var p = {
      amount: num('isAmount'), age: age, retire: num('isRetire'), rate: num('isReturn') / 100,
      withhold: num('isWithhold') / 100, exception: exception,
      excAmount: ex.cover === 'amount' ? num('isExcAmount') : 0,
      state: num('isState') / 100, retireTax: num('isRetireTax') / 100,
      tax: { mode: mode, rate: num('isFedRate') / 100, status: el('isStatus').value, income: num('isIncome') }
    };
    var error = el('isError'), msg = '';
    var needed = [p.amount, p.age, p.retire, p.rate, p.withhold, p.excAmount, p.state, p.retireTax,
                  mode === 'rate' ? p.tax.rate : p.tax.income];
    if (needed.some(isNaN)) msg = 'Fill in every field with a number.';
    else if (p.amount < 0 || p.excAmount < 0) msg = 'Enter amounts of 0 or more.';
    else if (p.age < 18 || p.age > 80 || p.retire > 90 || p.retire < p.age) msg = 'Enter an age from 18 to 80 and a retirement age from your age up to 90.';
    else if (p.rate < -0.2 || p.rate > 0.2) msg = 'Use a return from -20% to 20%.';
    else if (p.withhold < 0 || p.withhold > 1) msg = 'Withholding must be from 0% to 100%.';
    else if (p.state < 0 || p.state > 0.15 || p.retireTax < 0 || p.retireTax > 0.6) msg = 'Use a state rate from 0% to 15% and a retirement tax rate from 0% to 60%.';
    else if (mode === 'rate' ? (p.tax.rate < 0 || p.tax.rate > 0.37) : p.tax.income < 0) msg = mode === 'rate' ? 'Use a federal rate from 0% to 37%.' : 'Enter other income of 0 or more.';
    error.hidden = !msg;
    if (msg) {
      error.textContent = msg;
      OUTPUTS.forEach(function (id) { set(id, '–'); });
      set('isNote', '');
      el('isWarn').hidden = true;
      fillRows('isSchedule', []);
      return;
    }
    var r = compute(p);
    var retireLabel = ageText(p.retire);
    set('isKeepLabel', 'Kept invested, at age ' + retireLabel);
    set('isKeepAfterLabel', 'After tax at age ' + retireLabel);
    set('isNet', money(r.net));
    set('isKeep', money(r.value));
    set('isTaxes', money(r.totalTax));
    set('isKeepAfter', money(r.valueAfter));
    set('isGross', money(p.amount));
    set('isWithheldLabel', 'Federal tax withheld (' + (p.withhold * 100).toFixed(0) + '%)');
    set('isWithheld', money(r.withheld));
    set('isReceived', money(r.received));
    set('isFedLabel', 'Federal income tax (' + (p.amount > 0 ? (r.fed / p.amount * 100).toFixed(1) : '0.0') + '% of it, ' + TAX_YEAR + ')');
    set('isFed', money(r.fed));
    set('isAddl', p.age >= EARLY_AGE ? 'None' : money(r.addl));
    set('isStateTax', money(r.state));
    set('isSettleLabel', r.settle >= 0 ? 'Federal tax still owed at filing' : 'Federal refund of over-withholding');
    set('isSettle', money(Math.abs(r.settle)));

    var why;
    if (p.age >= EARLY_AGE) why = 'You are 59½ or older, so there is no 10% additional tax.';
    else if (p.amount > 0 && r.exempt >= p.amount - 0.005) why = 'Your exception covers the whole withdrawal, so there is no 10% additional tax.';
    else if (r.exempt > 0) why = 'Your exception covers ' + money(r.exempt) + '; the other ' + money(p.amount - r.exempt) + ' owes the 10% additional tax.';
    else why = 'You are under 59½, so the 10% additional tax applies.';
    set('isNote', why + ' Cashing out keeps ' + money(r.net) + ' today; left invested it could grow to ' + money(r.value) +
        ' by age ' + retireLabel + ' (' + money(r.valueAfter) + ' after tax).');
    var warn = el('isWarn');
    if (r.settle > 0.005) {
      warn.hidden = false;
      warn.textContent = 'The ' + (p.withhold * 100).toFixed(0) + '% withheld falls ' + money(r.settle) +
        ' short of the federal income tax and additional tax this withdrawal adds. Raise the withholding rate on Form W-4R or make an estimated payment to avoid an underpayment penalty. State tax is separate.';
    } else {
      warn.hidden = true;
    }
    fillRows('isSchedule', r.rows.map(function (row) {
      return [ageText(row.age), money(row.balance), money(row.balance * (1 - p.retireTax))];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('isForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
